menu.event:
if(dt < game.maxTickTime()) then local transitionState = element("transitionState"):GetInt() local transitionTime = element("transitionTime"):GetFloat()
if( transitionState ~= 0) then element:DoStoredScript("TickTransition")
if(transitionState == 1) then transitionTime = (transitionTime + dt*3) elseif(transitionState == 2) then transitionTime = (transitionTime - dt*3) end
transitionTime = clamp( transitionTime, 0.0, 1.0 ) element("transitionTime"):SetFloat(transitionTime)
if(transitionTime >= 1.0) then element("transitionState"):SetInt(0) element("transitionTime"):SetFloat(1.0) element:DoStoredScript("TickTransition") elseif(transitionTime <= 0.0) then element:root():popPopUp() end end end
